@ ============================================================================
@ gbamod1_data.s -- GBAModPlay v1 modules of Pinball Challenge Deluxe (E)
@ Three ROM ranges (other game data sits between them), rebuilt byte for byte by gbamod1.mk:
@   .gmp1_data0  0x0805993C-0x080A50E8  modules 0-2
@   .gmp1_data1  0x0814CCF4-0x081C8C5E  modules 3-6
@   .gmp1_data2  0x0826A58C-0x08316E1C  modules 7-10
@ Module 0 (one 60-row pattern, one sample) is the game's sound-effect module.
@
@ Module layout: +0x00 "GBAMOD1."  +0x08 pattern bytes  +0x0C sample bytes  +0x10 mix rate
@   +0x14 song length  +0x18 u32 step[296] (20.12 at 21024 Hz, 8 per semitone, 0 = B-0)
@   +0x4B8 31 sample headers {len, finetune, volume, loopStart, loopLen, 0}  +0x62C patterns
@   +0x630 order list[128]  +0x6B0 u8 rows[64]  +0x6F0 unused[64]  +0x730 patterns (4 channels,
@   only the stored rows)  then the 8-bit signed samples (gbamod1_samples_mN.bin)
@ Rows: R note,ins,cmd,par x 4.  note = step-table index, 8 = C-1 ... 288 = B-3; NONE = 0x1FF.
@ ============================================================================
	.syntax unified
	.macro CELL note, ins, cmd, par
	.hword (\ins << 9) | \note, (0x\cmd << 8) | 0x\par
	.endm
	.macro R note, ins, cmd, par, rest:vararg
	CELL \note, \ins, \cmd, \par
	.ifnb \rest
	R \rest
	.endif
	.endm
	.equ	NONE, 0x1FF
	.equ	C_1, 8
	.equ	C_2, 104
	.equ	C_3, 200
	.equ	C_4, 296
	.equ	Cs1, 16
